$('saveRun').onclick=()=>{let km=+$('runKm').value,min=+$('runMin').value;if(!(km>0)||!(min>0)){alert('اكتب المسافة والمدة بشكل صحيح.');return}addLog({type:'run',who:current,title:'جري',km,min,pace:Math.round((min/km)*100)/100,date:$('runDate').value||today()});addPoints(current,Math.round(km*5));$('runKm').value='';$('runMin').value='';$('runPace').value=''};
function updateWalkFields(){const mode=$('walkMode')?.value||'time';['time','distance','steps'].forEach(k=>{const el=$('walk'+({time:'Time',distance:'Distance',steps:'Steps'}[k])+'Field');if(el)el.classList.toggle('hidden',mode!==k)})}if($('walkMode')){$('walkMode').addEventListener('change',updateWalkFields);updateWalkFields()}$('saveExercise').onclick=()=>{const mode=$('walkMode').value,date=$('exerciseDate').value||today();let min=0,km=0,steps=0;if(mode==='time'){min=+$('walkMin').value;if(!(min>0)){alert('اكتب مدة المشي.');return}km=min*0.075;steps=Math.round(km*1300)}else if(mode==='distance'){km=+$('walkKm').value;if(!(km>0)){alert('اكتب مسافة صحيحة.');return}min=Math.round(km/4.5*60);steps=Math.round(km*1300)}else{steps=+$('walkSteps').value;if(!(steps>0)){alert('اكتب عدد خطوات صحيح.');return}km=steps/1300;min=Math.round(km/4.5*60)}addLog({type:'walk',who:current,title:'مشي',mode,min,km:+km.toFixed(2),steps,date});addPoints(current,Math.max(1,Math.round(steps/1000)));['walkMin','walkKm','walkSteps'].forEach(id=>{if($(id))$(id).value=''});showFoodToast('✓ تم تسجيل المشي');showSuccessPulse('اتسجل نشاطك','كل خطوة بتفرق 👟');};
$('saveSleep').onclick=()=>{let hours=+$('sleepHours').value;if(!(hours>0&&hours<=24)){alert('اكتب عدد ساعات صحيح.');return}const sleepDate=$('sleepDate').value||today();db.logs=db.logs.filter(x=>!(x.type==='sleep'&&x.who===current&&x.date===sleepDate));addLog({type:'sleep',who:current,title:'نوم',hours,date:sleepDate});addPoints(current,3);$('sleepHours').value=''};
$('foodSearch').addEventListener('focus',()=>{foodPickerOpen=true;renderFood()});$('foodSearch').addEventListener('input',()=>{foodPickerOpen=true;renderFood()});$('toggleFoodList').addEventListener('click',()=>{foodPickerOpen=!foodPickerOpen;renderFood();$('toggleFoodList').setAttribute('aria-expanded',String(foodPickerOpen));$('toggleFoodList').textContent=foodPickerOpen?'إخفاء الأصناف':'🍽️ عرض الأصناف'});function renderFood(){if(!foods.length)return;const cats=['الكل','أكل','مشروب','سوبر ماركت'];$('categories').innerHTML=cats.map(c=>`<button class="chip ${category===c?'active':''}" data-cat="${c}">${c==='الكل'?'الكل':c==='أكل'?'🍽️ أكل':c==='مشروب'?'🥤 مشروبات':'🛒 سوبر ماركت'}</button>`).join('');$('categories').querySelectorAll('button').forEach(b=>b.onclick=()=>{category=b.dataset.cat;foodPickerOpen=true;renderFood()});let q=$('foodSearch').value.trim().toLowerCase();let list=foods.filter(f=>(category==='الكل'||f.cat===category)&&f.name.toLowerCase().includes(q));$('categories').classList.toggle('hidden',!foodPickerOpen);$('foodList').classList.toggle('hidden',!foodPickerOpen);$('toggleFoodList').setAttribute('aria-expanded',String(foodPickerOpen));$('toggleFoodList').textContent=foodPickerOpen?'إخفاء الأصناف':'🍽️ عرض الأصناف';$('foodList').innerHTML=list.map(f=>`<button class="food-item ${selected&&selected.id===f.id?'active':''}" data-id="${f.id}"><strong>${f.name}</strong><small>${f.cat} · ${f.kcal} سعر / حصة</small></button>`).join('')||'<p class="muted">مفيش نتائج. جرّب اسم تاني.</p>';document.querySelectorAll('.food-item').forEach(b=>b.onclick=()=>{selected=foods.find(f=>f.id===+b.dataset.id);$('grams').value='';$('foodCount').value=1;foodPickerOpen=false;renderFood();renderFacts()});if(selected)renderFacts()}
$('grams').addEventListener('input',renderFacts);$('foodCount').addEventListener('input',renderFacts);function baseGrams(f){let s=(f.serving||'').replace(/,/g,'');let m=s.match(/(\d+(?:\.\d+)?)\s*(?:جم|غرام|جرام|مل)/);if(m)return +m[1];if(/بيضة/.test(s))return 50;if(/كوب/.test(s))return 200;if(/موزة/.test(s))return 120;if(/شريحة/.test(s))return 30;return 100}function foodValues(){let gramsText=$('grams').value.trim(),count=Math.max(0,+$('foodCount').value||0),g=gramsText?Math.max(0,+gramsText):baseGrams(selected)*count,scale=g/baseGrams(selected);return {g,count,kcal:selected.kcal*scale,protein:selected.protein*scale,carbs:selected.carbs*scale,fat:selected.fat*scale,fiber:selected.fiber*scale}}function renderFacts(){if(!selected)return;$('chosenName').textContent=selected.name;$('chosenServing').textContent=`الحصة المرجعية: ${selected.serving} · الحساب نسبي للكمية`;let n=foodValues();$('nutritionFacts').innerHTML=[['السعرات',num(n.kcal),'سعرة','#ff944d'],['بروتين',num(n.protein,1),'جم','#77c8ff'],['كربوهيدرات',num(n.carbs,1),'جم','#d7adff'],['دهون',num(n.fat,1),'جم','#ffd166'],['ألياف',num(n.fiber,1),'جم','#72d6a1']].map(a=>`<div class="fact" style="--fact:${a[3]}"><small>${a[0]}</small><strong>${a[1]} <small>${a[2]}</small></strong></div>`).join('')}
function makeFoodEntry(){let n=foodValues();return {type:'food',who:current,title:selected.name,meal:$('mealType').value,grams:Math.round(n.g*10)/10,count:n.count,kcal:Math.round(n.kcal),protein:+n.protein.toFixed(1),carbs:+n.carbs.toFixed(1),fat:+n.fat.toFixed(1),fiber:+n.fiber.toFixed(1)}}
function renderMealBasket(){const box=$('mealBasketItems');if(!box)return;box.innerHTML=mealBasket.length?mealBasket.map((x,i)=>`<div class="basket-row"><div><strong>${x.title}</strong><small>${num(x.grams,1)} جم/مل · ${x.meal}</small><small>${x.kcal} سعرة · بروتين ${x.protein} جم</small></div><div class="basket-controls"><button type="button" class="qty-btn" data-remove-food="${i}" aria-label="حذف الصنف">×</button></div></div>`).join(''):'<p class="muted">لسه ما ضفتش أصناف.</p>';box.querySelectorAll('[data-remove-food]').forEach(b=>b.onclick=()=>{mealBasket.splice(+b.dataset.removeFood,1);renderMealBasket()});let total=mealBasket.reduce((a,x)=>({kcal:a.kcal+x.kcal,protein:a.protein+x.protein,carbs:a.carbs+x.carbs,fat:a.fat+x.fat,fiber:a.fiber+x.fiber}),{kcal:0,protein:0,carbs:0,fat:0,fiber:0});$('mealBasketTotals').innerHTML=mealBasket.length?[['السعرات',Math.round(total.kcal),'سعرة','#ff944d'],['بروتين',num(total.protein,1),'جم','#77c8ff'],['كربوهيدرات',num(total.carbs,1),'جم','#d7adff'],['دهون',num(total.fat,1),'جم','#ffd166']].map(a=>`<div class="fact" style="--fact:${a[3]}"><small>${a[0]}</small><strong>${a[1]} <small>${a[2]}</small></strong></div>`).join(''):'';$('saveMealBasket').disabled=!mealBasket.length}
$('logFood').onclick=()=>{if(!selected){alert('اختار صنف الأول.');return}let n=foodValues();if(n.g<=0){alert('اكتب كمية بالجرام أو عدد حصص أكبر من صفر.');return}mealBasket.push(makeFoodEntry());renderMealBasket();$('logFood').textContent='✓ اتضاف للوجبة · أضف صنف تاني';setTimeout(()=>{if($('logFood'))$('logFood').textContent='+ أضف الصنف للوجبة'},900)};
$('saveMealBasket').onclick=()=>{if(!mealBasket.length)return;const now=Date.now();mealBasket.forEach((item,i)=>db.logs.push({...item,id:now+i+Math.random(),createdAt:now,date:today()}));addPoints(current,2);mealBasket=[];save();renderMealBasket();renderAll();$('logFood').textContent='+ أضف الصنف للوجبة';showSuccessPulse('اتسجلت وجبتك بنجاح',`تمت إضافة الأكل إلى يومك`)};
$('clearMealBasket').onclick=()=>{mealBasket=[];renderMealBasket();$('logFood').textContent='+ أضف الصنف للوجبة'};

// AI food photo flow. Calls a Supabase Edge Function so the provider key never ships to the browser.
let aiFoodPhotoData=null,aiFoodPhotoMime='image/jpeg',aiFoodDraft=[];
const aiNum=(v)=>Math.max(0,Number(v)||0);
function aiTotals(){return aiFoodDraft.reduce((a,x)=>{a.kcal+=aiNum(x.kcal);a.protein+=aiNum(x.protein);a.carbs+=aiNum(x.carbs);a.fat+=aiNum(x.fat);return a},{kcal:0,protein:0,carbs:0,fat:0})}
function renderAiFoodDraft(){const box=$('aiFoodItems');if(!box)return;box.innerHTML=aiFoodDraft.map((x,i)=>`<div class="ai-food-item" data-ai-item="${i}"><div class="ai-food-item-head"><input data-ai-field="name" aria-label="اسم الصنف" value="${String(x.name||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}" placeholder="اسم الصنف"><button class="secondary ai-remove-item" type="button" data-ai-remove="${i}" aria-label="حذف الصنف">×</button></div><div class="ai-food-item-grid"><label>الكمية جم<input data-ai-field="grams" type="number" min="1" value="${aiNum(x.grams)||100}"></label><label>السعرات<input data-ai-field="kcal" type="number" min="0" value="${Math.round(aiNum(x.kcal))}"></label><label>بروتين جم<input data-ai-field="protein" type="number" min="0" step="0.1" value="${aiNum(x.protein)}"></label><label>كارب جم<input data-ai-field="carbs" type="number" min="0" step="0.1" value="${aiNum(x.carbs)}"></label><label>دهون جم<input data-ai-field="fat" type="number" min="0" step="0.1" value="${aiNum(x.fat)}"></label></div></div>`).join('');box.querySelectorAll('[data-ai-remove]').forEach(b=>b.onclick=()=>{aiFoodDraft.splice(+b.dataset.aiRemove,1);renderAiFoodDraft();syncAiTotals()});box.querySelectorAll('[data-ai-field]').forEach(inp=>inp.addEventListener('input',()=>{const row=inp.closest('[data-ai-item]');const i=+row.dataset.aiItem;const key=inp.dataset.aiField;aiFoodDraft[i][key]=key==='name'?inp.value:aiNum(inp.value);syncAiTotals()}));}
function syncAiTotals(){const t=aiTotals();[['aiTotalKcal','kcal',0],['aiTotalProtein','protein',1],['aiTotalCarbs','carbs',1],['aiTotalFat','fat',1]].forEach(([id,k,d])=>{if($(id))$(id).value=d? t[k].toFixed(1):Math.round(t[k])})}
function openAiFood(){ $('aiFoodModal').classList.remove('hidden');$('aiFoodStatus').textContent='اختار صورة واضحة للأكل.'; }
function closeAiFood(){ $('aiFoodModal').classList.add('hidden'); }
$('openFoodCamera')?.addEventListener('click',openAiFood);$('closeAiFood')?.addEventListener('click',closeAiFood);$('aiFoodModal')?.addEventListener('click',e=>{if(e.target===$('aiFoodModal'))closeAiFood()});
$('aiFoodImage')?.addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('image/')){showFoodToast('اختار ملف صورة صحيح');return}if(f.size>12*1024*1024){showFoodToast('حجم الصورة لازم يكون أقل من 12 ميجابايت');e.target.value='';return}aiFoodPhotoMime=f.type;aiFoodPhotoData=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(f)});$('aiFoodPreview').src=URL.createObjectURL(f);$('aiFoodPreview').classList.remove('hidden');$('analyzeAiFood').disabled=false;$('aiFoodStatus').textContent='الصورة جاهزة للتحليل.';$('aiFoodEditor').classList.add('hidden')});
$('analyzeAiFood')?.addEventListener('click',async()=>{if(!aiFoodPhotoData)return;const btn=$('analyzeAiFood');btn.disabled=true;$('aiFoodStatus').textContent='جاري تحليل الصورة…';try{const {data,error}=await sb.functions.invoke('analyze-food',{body:{imageBase64:aiFoodPhotoData,mimeType:aiFoodPhotoMime}});if(error)throw error;const rawFoods=Array.isArray(data?.foods)?data.foods:(Array.isArray(data?.items)?data.items:[]);const arr=rawFoods.map(x=>({name:x.name,grams:x.grams??x.quantity??100,kcal:x.kcal??x.calories??0,protein:x.protein??0,carbs:x.carbs??0,fat:x.fat??0}));if(!arr.length)throw new Error('لم أتعرف على أصناف واضحة. جرّب صورة أوضح أو أضف الأصناف يدويًا.');aiFoodDraft=arr.map(x=>({name:String(x.name||'صنف غير معروف').slice(0,100),grams:Math.max(1,aiNum(x.grams)||100),kcal:aiNum(x.kcal),protein:aiNum(x.protein),carbs:aiNum(x.carbs),fat:aiNum(x.fat)}));renderAiFoodDraft();syncAiTotals();$('aiFoodEditor').classList.remove('hidden');$('aiFoodStatus').textContent=(data.note||data.notes||'تقدير تقريبي من الصورة. عدّل الكميات والقيم حسب وجبتك.');}catch(err){console.error('AI food analysis failed',err);$('aiFoodStatus').textContent='التحليل بالـ AI مش متصل أو حصل خطأ. راجع إعداد Supabase Edge Function في ملف AI_FOOD_SETUP_AR.md. تقدر تضيف الأصناف يدويًا.';$('aiFoodEditor').classList.remove('hidden');if(!aiFoodDraft.length){aiFoodDraft=[{name:'صنف 1',grams:100,kcal:0,protein:0,carbs:0,fat:0}];renderAiFoodDraft();syncAiTotals()}}finally{btn.disabled=false}});
$('addAiFoodItem')?.addEventListener('click',()=>{aiFoodDraft.push({name:'صنف جديد',grams:100,kcal:0,protein:0,carbs:0,fat:0});renderAiFoodDraft();syncAiTotals()});
$('saveAiFood')?.addEventListener('click',()=>{if(!aiFoodDraft.length){showFoodToast('أضف صنفًا واحدًا على الأقل');return}const valid=aiFoodDraft.filter(x=>String(x.name||'').trim());if(!valid.length){showFoodToast('اكتب اسم صنف واحد على الأقل');return}const totals=aiTotals(),target={kcal:aiNum($('aiTotalKcal').value),protein:aiNum($('aiTotalProtein').value),carbs:aiNum($('aiTotalCarbs').value),fat:aiNum($('aiTotalFat').value)};const scale=(key)=>totals[key]>0?target[key]/totals[key]:1;const meal=$('aiMealType').value,now=Date.now();valid.forEach((x,i)=>{const factor=aiNum(x.grams)/Math.max(1,aiNum(x.grams));db.logs.push({type:'food',who:current,title:String(x.name).trim(),meal,grams:aiNum(x.grams)||100,count:1,kcal:Math.round(target.kcal!==totals.kcal?aiNum(x.kcal)*scale('kcal'):aiNum(x.kcal)),protein:+(target.protein!==totals.protein?aiNum(x.protein)*scale('protein'):aiNum(x.protein)).toFixed(1),carbs:+(target.carbs!==totals.carbs?aiNum(x.carbs)*scale('carbs'):aiNum(x.carbs)).toFixed(1),fat:+(target.fat!==totals.fat?aiNum(x.fat)*scale('fat'):aiNum(x.fat)).toFixed(1),fiber:0,id:now+i+Math.random(),createdAt:now,date:today(),source:'ai-photo'});});addPoints(current,2);save();renderAll();closeAiFood();showSuccessPulse('اتسجلت وجبتك بنجاح',`تم تسجيل ${valid.length} أصناف في يومك`);aiFoodDraft=[];aiFoodPhotoData=null;$('aiFoodImage').value='';$('aiFoodPreview').classList.add('hidden');$('aiFoodEditor').classList.add('hidden')});


function showSuccessPulse(title,subtitle='تم تحديث يومك'){let el=$('successPulse');if(!el){el=document.createElement('div');el.id='successPulse';el.className='success-pulse';el.setAttribute('role','status');el.setAttribute('aria-live','polite');el.innerHTML='<div class="success-pulse-card"><div class="success-check-wrap"><svg viewBox="0 0 52 52" aria-hidden="true"><circle class="success-check-circle" cx="26" cy="26" r="23"/><path class="success-check-mark" d="M14 27l8 8 16-18"/></svg></div><strong class="success-title"></strong><span class="success-subtitle"></span></div>';document.body.appendChild(el)}el.querySelector('.success-title').textContent=title;el.querySelector('.success-subtitle').textContent=subtitle;el.classList.remove('show');void el.offsetWidth;el.classList.add('show');clearTimeout(window.__successPulseTimer);window.__successPulseTimer=setTimeout(()=>el.classList.remove('show'),1750)}
function showFoodToast(message){let t=$('foodToast');if(!t){t=document.createElement('div');t.id='foodToast';t.className='food-toast';t.setAttribute('role','status');document.body.appendChild(t)}t.textContent=message;t.classList.add('show');clearTimeout(window.__foodToastTimer);window.__foodToastTimer=setTimeout(()=>t.classList.remove('show'),2400)}
function renderList(id,items,formatter,empty='لسه مفيش تسجيلات.'){let sorted=[...items].sort((a,b)=>(b.date||'').localeCompare(a.date||''));$(id).innerHTML=sorted.length?sorted.map(x=>`<div class="log-item"><div><strong>${x.title}</strong><small>${NAMES[x.who]||x.who} · ${prettyDate(x.date)}${x.meal?' · '+x.meal:''}</small></div><div class="log-right">${formatter(x)}${id==='foodLog'&&x.who===current?`<div class="food-log-actions"><button type="button" class="secondary compact" data-edit-meal="${x.id}">تعديل</button><button type="button" class="secondary compact danger-action" data-delete-meal="${x.id}">حذف</button></div>`:''}${['activityLog','activityHistoryLog'].includes(id)&&x.who===current?`<div class="food-log-actions"><button type="button" class="secondary compact danger-action" data-delete-activity="${x.id}">حذف النشاط</button></div>`:''}</div></div>`).join(''):`<p class="muted">${empty}</p>`;if(id==='foodLog'){ $(id).querySelectorAll('[data-delete-meal]').forEach(b=>b.onclick=()=>{const entry=db.logs.find(x=>String(x.id)===b.dataset.deleteMeal&&x.type==='food'&&x.who===current);if(!entry)return;if(!confirm(`تحذف وجبة «${entry.title}»؟`))return;db.logs=db.logs.filter(x=>x!==entry);save();renderAll();showFoodToast('✓ تم حذف الوجبة وتحديث السعرات')});$(id).querySelectorAll('[data-edit-meal]').forEach(b=>b.onclick=()=>{const entry=db.logs.find(x=>String(x.id)===b.dataset.editMeal&&x.type==='food'&&x.who===current);if(!entry)return;const grams=prompt('عدّل الكمية بالجرام/مل:',String(entry.grams||100));if(grams===null)return;const g=Number(grams);if(!Number.isFinite(g)||g<=0){showFoodToast('اكتب كمية صحيحة أكبر من صفر');return}const old=Math.max(0.001,Number(entry.grams)||100),ratio=g/old;const meal=prompt('نوع الوجبة (فطار، غداء، عشاء، سناك، مشروب):',entry.meal||'سناك');if(meal===null)return;entry.grams=Math.round(g*10)/10;entry.kcal=Math.round((+entry.kcal||0)*ratio);['protein','carbs','fat','fiber'].forEach(k=>entry[k]=+((+entry[k]||0)*ratio).toFixed(1));entry.meal=meal.trim()||entry.meal;entry.updatedAt=Date.now();save();renderAll();showFoodToast('✓ تم تعديل الوجبة وتحديث القيم الغذائية')});}if(['activityLog','activityHistoryLog'].includes(id)){ $(id).querySelectorAll('[data-delete-activity]').forEach(b=>b.onclick=()=>{const entry=db.logs.find(x=>String(x.id)===b.dataset.deleteActivity&&['run','walk','exercise','workout'].includes(x.type)&&x.who===current);if(!entry)return;if(!confirm(`تحذف نشاط «${entry.title|| (entry.type==='walk'?'مشي':entry.type==='run'?'جري':'تمرين')}» من سجلك؟`))return;db.logs=db.logs.filter(x=>x!==entry);db.deletedLogIds=[...new Set([...(db.deletedLogIds||[]).map(String),String(entry.id)])];sharedState.deletedLogIds=[...new Set([...(sharedState.deletedLogIds||[]).map(String),String(entry.id)])];sharedState.logs=(sharedState.logs||[]).filter(x=>String(x.id)!==String(entry.id));save();renderAll();persistRemote().catch(err=>{console.error('Activity deletion sync failed:',err);showFoodToast('اتحذف من الجهاز، لكن المزامنة فشلت؛ تحقق من الاتصال')});showFoodToast('✓ تم حذف النشاط من السجل')});}}
function personCard(who){let runs=sumRun(who),walks=sumWalk(who),ex=ownLogs(who).filter(x=>['run','exercise','workout','walk'].includes(x.type)).length;return `<article class="person-card ${who===current?'me-card':''}"><h3>${who===current?'⭐ ':''}${NAMES[who]}</h3><div class="mini"><span>إجمالي الجري</span><b>${num(runs,2)} كم</b></div><div class="mini"><span>إجمالي المشي</span><b>${num(walks,2)} كم</b></div><div class="mini"><span>الأنشطة</span><b>${ex}</b></div></article>`}
function renderRunHistory(){let chosen=$('runHistoryDate')?.value||'';let runs=db.logs.filter(x=>x.type==='run'&&(!chosen||x.date===chosen));if($('runHistoryCaption'))$('runHistoryCaption').textContent=chosen?`جريات يوم ${prettyDate(chosen)} — عمرو وزياد`:`كل الجريات المسجلة لعمرو وزياد، مرتبة من الأحدث للأقدم`;renderList('runHistory',runs,x=>`<b>${num(x.km,2)} كم</b><br><small>${x.min||'—'} دقيقة${x.pace?' · بيس '+x.pace:''}</small>`,'مفيش جريات في التاريخ ده.');}
$('runHistoryDate')?.addEventListener('change',renderRunHistory);$('clearRunDate')?.addEventListener('click',()=>{$('runHistoryDate').value='';renderRunHistory()});
function compareIcon(kind){const paths={ruler:'<path d="M4 16 16 4l4 4L8 20z"/><path d="m12 8 2 2m-5 1 2 2m-5 1 2 2"/>',weight:'<path d="M6 7h12l2 13H4z"/><path d="M9 7a3 3 0 0 1 6 0"/>',calories:'<path d="M12 22c4 0 7-3 7-7 0-3-2-5-4-7 0 3-2 4-2 4 0-4-2-7-5-10 1 5-4 8-4 13 0 4 3 7 8 7Z"/><path d="M12 22c-2 0-3-2-3-4 0-2 2-3 3-5 2 2 3 3 3 5 0 2-1 4-3 4Z"/>',water:'<path d="M12 3S5 11 5 15a7 7 0 0 0 14 0c0-4-7-12-7-12Z"/><path d="M9 16a3 3 0 0 0 3 3"/>',sleep:'<path d="M19 15A8 8 0 0 1 9 5a8 8 0 1 0 10 10Z"/><path d="M16 4v4m-2-2h4"/>'};return `<svg class="compare-icon-svg icon-${kind}" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" role="img" aria-label="${kind}" style="display:block;width:24px;height:24px;min-width:24px;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round">${paths[kind]||''}</svg>`}
function compareNeedCard(who){const p=getProfile(who);const logs=ownLogs(who).filter(x=>x.date===today());const eaten=logs.filter(x=>x.type==='food').reduce((s,x)=>s+(+x.kcal||0),0);const water=logs.filter(x=>x.type==='water').reduce((s,x)=>s+(Number(x.ml)||0),0);const sleep=ownLogs(who,'sleep').filter(x=>x.date===today()).sort((a,b)=>(Number(b.createdAt)||Number(b.id)||0)-(Number(a.createdAt)||Number(a.id)||0))[0];const slept=sleep?Math.max(0,+sleep.hours||0):0;const calGoal=p?p.calories:0,waterGoal=p?p.water:0,sleepGoal=8;const remainCal=Math.max(0,calGoal-eaten),remainWater=Math.max(0,waterGoal-water),remainSleep=Math.max(0,sleepGoal-slept);const pct=(a,b)=>b?Math.min(100,a/b*100):0;return `<article class="panel compare-needs-card ${who===current?'me-card':''}"><h3>${who===current?'⭐ ':''}${NAMES[who]}</h3>${p?`<div class="compare-body-stats"><span><i class="compare-body-icon ruler-icon">${compareIcon('ruler')}</i><span>الطول</span><b>${num(p.height)} سم</b></span><span><i class="compare-body-icon weight-icon">${compareIcon('weight')}</i><span>الوزن</span><b>${num(p.weight)} كجم</b></span></div><div class="compare-metric"><div class="compare-metric-head"><span class="compare-metric-label"><i class="compare-metric-icon calories-icon">${compareIcon('calories')}</i>السعرات</span><b>${num(eaten)} / ${num(calGoal)} سعرة</b></div><div class="progress"><span style="width:${pct(eaten,calGoal)}%"></span></div><small>المتبقي: ${num(remainCal)} سعرة${eaten>calGoal?' · تجاوزت الهدف بـ '+num(eaten-calGoal):''}</small></div><div class="compare-metric"><div class="compare-metric-head"><span class="compare-metric-label"><i class="compare-metric-icon water-icon">${compareIcon('water')}</i>المياه</span><b>${num(water)} / ${num(waterGoal)} مل</b></div><div class="progress water-progress"><span style="width:${pct(water,waterGoal)}%"></span></div><small>المتبقي: ${num(remainWater)} مل${water>waterGoal?' · تجاوزت الهدف بـ '+num(water-waterGoal)+' مل':''}</small></div>`:`<p class="muted">احتياج السعرات والمياه غير متاح. أكمل بيانات الجسم لهذا الحساب.</p>`}<div class="compare-metric"><div class="compare-metric-head"><span class="compare-metric-label"><i class="compare-metric-icon sleep-icon">${compareIcon('sleep')}</i>النوم</span><b>${num(slept,1)} / ${sleepGoal} ساعات</b></div><div class="progress sleep-progress"><span style="width:${pct(slept,sleepGoal)}%"></span></div><small>${sleep?'المتبقي للوصول إلى 8 ساعات: '+num(remainSleep,1)+' ساعة':'لم يتم تسجيل النوم اليوم · الهدف 8 ساعات'}</small></div></article>`}
function renderCompare(){const other=current==='Amr'?'Ziad':'Amr';const duoLabel=`أنا و${NAMES[other]}`;if($('compareNavLabel'))$('compareNavLabel').textContent=duoLabel;if($('comparePageTitle'))$('comparePageTitle').textContent=duoLabel;if($('homeCompareTitle'))$('homeCompareTitle').textContent=`${NAMES[current]} و${NAMES[other]}`;$('compareCards').innerHTML=PEOPLE.map(personCard).join('');$('homeCompare').innerHTML=PEOPLE.map(personCard).join('');if($('compareNeedsCards'))$('compareNeedsCards').innerHTML=PEOPLE.map(compareNeedCard).join('');let max=Math.max(1,...PEOPLE.map(sumRun));$('runCompare').innerHTML=PEOPLE.map(p=>{let km=sumRun(p);return `<div class="barrow"><b>${NAMES[p]}</b><div class="bar"><span style="width:${km/max*100}%"></span></div><strong>${num(km,2)} كم</strong></div>`}).join('');if($('walkCompare'))$('walkCompare').innerHTML=PEOPLE.map(p=>{let km=sumWalk(p),maxWalk=Math.max(1,...PEOPLE.map(sumWalk));return `<div class="barrow"><b>${NAMES[p]}</b><div class="bar"><span style="width:${km/maxWalk*100}%;background:linear-gradient(90deg,#39c7ff,#70e0b0)"></span></div><strong>${num(km,2)} كم</strong></div>`}).join('');renderRunHistory();renderList('teamActivity',db.logs.filter(x=>['run','walk','exercise','workout'].includes(x.type)),x=>x.type==='run'?`<b>🏃 جري · ${num(x.km,2)} كم</b><br><small>${num(x.min)} دقيقة · بيس ${num(x.pace||((+x.min||0)/(+x.km||1)),2)} دقيقة/كم</small>`:x.type==='walk'?`<b>🚶 مشي</b><br><small>${x.steps?num(x.steps)+' خطوة · ':''}${num(x.km,2)} كم · ${num(x.min)} دقيقة</small>`:x.type==='workout'?`<b>💪 ${x.title}</b><br><small>${x.sets||0} مجموعات × ${x.reps||'—'} عدة</small>`:`<b>🏋️ نشاط · ${x.title||'تمرين'}</b><br><small>${num(x.min)} دقيقة</small>`,'مفيش أنشطة رياضية مسجلة.')}
function dayKey(){return today()}function weekKey(){let d=new Date();let jan=new Date(d.getFullYear(),0,1);let w=Math.ceil((((d-jan)/86400000)+jan.getDay()+1)/7);return `${d.getFullYear()}-W${w}`}function seededIndex(seed,len){let h=0;for(let i=0;i<seed.length;i++)h=(h*31+seed.charCodeAt(i))>>>0;return h%len}const dailyPool=[{title:'اشرب 1500 مل مياه',type:'water',target:1500,unit:'مل'},{title:'سجّل وجبة فيها بروتين',type:'protein',target:1,unit:'وجبة'},{title:'تحرك 20 دقيقة',type:'minutes',target:20,unit:'دقيقة'},{title:'اجري 2 كم مع بعض',type:'run',target:2,unit:'كم'},{title:'سجّل 3 وجبات',type:'meals',target:3,unit:'وجبة'},{title:'اعمل 30 دقيقة كاليستنكس أو مقاومة',type:'exercise',target:30,unit:'دقيقة'},{title:'كل فاكهة النهارده',type:'fruit',target:1,unit:'مرة'}];const weeklyPool=[{title:'اجمعوا 3 جريات',type:'runs',target:3,unit:'جريات'},{title:'اجمعوا 10 كم جري',type:'run',target:10,unit:'كم'},{title:'سجّلوا 5 تمارين',type:'exercise',target:5,unit:'تمارين'},{title:'سجّلوا 20 وجبة',type:'meals',target:20,unit:'وجبة'},{title:'اشربوا 14 لتر مياه مع بعض',type:'water',target:14000,unit:'مل'}];function challengeProgress(c,period){let logs=db.logs.filter(x=>period==='day'?x.date===today():x.date&&x.date.slice(0,4)===new Date().getFullYear().toString()&&weekOf(x.date)===weekKey());switch(c.type){case'water':return logs.filter(x=>x.type==='water').reduce((s,x)=>s+(Number(x.ml)||0),0);case'protein':return logs.filter(x=>x.type==='food'&&x.protein>=15).length;case'minutes':return logs.filter(x=>x.type==='exercise'||x.type==='run'||x.type==='walk').reduce((s,x)=>s+(x.min||0),0);case'run':return logs.filter(x=>x.type==='run').reduce((s,x)=>s+(x.km||0),0);case'meals':return logs.filter(x=>x.type==='food').length;case'exercise':return logs.filter(x=>x.type==='exercise'||x.type==='walk').reduce((s,x)=>s+(x.min||0),0);case'fruit':return logs.filter(x=>x.type==='food'&&/فاكه|تفاح|موز|برتقال|مانجو|عنب|فراول|تمر/.test(x.title)).length;case'runs':return logs.filter(x=>x.type==='run').length;default:return 0}}function weekOf(date){let d=new Date(date+'T12:00:00'),jan=new Date(d.getFullYear(),0,1);return `${d.getFullYear()}-W${Math.ceil((((d-jan)/86400000)+jan.getDay()+1)/7)}`}function challengeHTML(c,period){let n=challengeProgress(c,period),done=n>=c.target;return `<div class="challenge"><strong>${done?'✅':'🎯'} ${c.title}</strong><div class="progress"><span style="width:${Math.min(100,n/c.target*100)}"></span></div><small>${num(n,1)} / ${c.target} ${c.unit}</small></div>`}function renderChallenges(){let daily=dailyPool[seededIndex(dayKey(),dailyPool.length)],weekly=weeklyPool[seededIndex(weekKey(),weeklyPool.length)];$('homeDailyChallenge').innerHTML=challengeHTML(daily,'day')+`<small class="muted">يتجدد يوم ${prettyDate(today())}</small>`;$('dailyChallenges').innerHTML=challengeHTML(daily,'day');$('weeklyChallenges').innerHTML=challengeHTML(weekly,'week')+`<small class="muted">أسبوع ${weekKey()}</small>`}
$('planForm').addEventListener('submit',e=>{e.preventDefault();let plan={id:Date.now()+Math.random(),who:current,day:+$('planDay').value,type:$('planType').value,details:$('planDetails').value.trim(),target:+$('planTarget').value||0};if(!plan.details)return;db.plans.push(plan);save();$('planDetails').value='';$('planTarget').value='';renderPlan()});function renderPlan(){let days=['الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];$('weeklyPlan').innerHTML=days.map((d,i)=>{let plans=db.plans.filter(p=>p.day===i&&p.who===current);return `<div class="panel day-panel"><h3>${d}</h3>${plans.length?plans.map(p=>{let done=db.planDone.some(x=>x.planId===p.id&&x.date===today());return `<div class="plan-row"><div><strong>${p.details}</strong><small>${p.type} · ${NAMES[p.who]||'مشترك'}</small></div><button class="${done?'donebtn':'secondary compact'}" data-complete-plan="${p.id}" ${done?'disabled':''}>${done?'تم ✓':'خلصت'}</button><button class="deletebtn" data-delete-plan="${p.id}" aria-label="حذف">×</button></div>`}).join(''):'<p class="muted">مفيش نشاط مضاف لليوم ده.</p>'}</div>`}).join('');$('weeklyPlan').querySelectorAll('[data-complete-plan]').forEach(b=>b.onclick=()=>completePlan(b.dataset.completePlan));$('weeklyPlan').querySelectorAll('[data-delete-plan]').forEach(b=>b.onclick=()=>{db.plans=db.plans.filter(p=>String(p.id)!==b.dataset.deletePlan);save();renderPlan()});renderList('planHistory',db.planDone.filter(x=>x.who===current),x=>`<b>✓ تم</b><br><small>${x.details}</small>`,'لسه مفيش أنشطة مكتملة من الجدول.')}function completePlan(id){let p=db.plans.find(x=>String(x.id)===String(id));if(!p||db.planDone.some(x=>x.planId===p.id&&x.date===today()))return;let who=current;let log={type:p.type==='جري'?'run':'exercise',who,title:p.type==='جري'?'جري (من الجدول)':p.type,min:p.type==='جري'?0:(p.target||30),km:p.type==='جري'?(p.target||0):0,date:today(),fromPlan:true};if(log.type==='run'&&log.km<=0){let m=p.details.match(/([0-9.]+)\s*كم/);log.km=m?+m[1]:0}db.logs.push({...log,id:Date.now()+Math.random()});addPoints(who,10);db.planDone.push({planId:p.id,date:today(),who:p.who,title:p.type,details:p.details});save();renderAll()}
function renderNeeds(){let p=getProfile(current);if(!p){$('calGoal').textContent='—';$('calEaten').textContent='أكمل بياناتك أولًا';$('waterGoal').textContent='—';$('waterToday').textContent='أكمل بياناتك أولًا';$('sleepValue').textContent='—';$('sleepQuality').textContent='سجّل نومك';if($('needsSummary'))$('needsSummary').innerHTML='<p class="muted">أدخل الوزن والطول والسن من بياناتك لحساب احتياجك اليومي.</p>';['calGauge','waterGauge','sleepGauge'].forEach(id=>$(id).style.setProperty('--progress','0%'));return;}let todayLogs=ownLogs(current).filter(x=>x.date===today());let foodToday=todayLogs.filter(x=>x.type==='food');let eaten=foodToday.reduce((s,x)=>s+(+x.kcal||0),0),water=todayLogs.filter(x=>x.type==='water').reduce((s,x)=>s+(Number(x.ml)||0),0),exerciseBurn=todayLogs.reduce((s,x)=>s+(x.type==='run'||x.type==='walk'?((+x.km||0)*p.weight):x.type==='exercise'?((+x.min||0)*(x.intensity==='عالٍ'?9:x.intensity==='خفيف'?3:5)*p.weight/60):0),0);let calorieGoal=Math.round(p.calories+exerciseBurn),waterGoal=p.water+Math.round(todayLogs.reduce((s,x)=>s+(x.type==='run'?(+x.min||0)*8:(x.type==='exercise'||x.type==='walk')?(+x.min||0)*5:0),0)/50)*50;let sleep=ownLogs(current,'sleep').filter(x=>x.date===today()).sort((a,b)=>b.id-a.id)[0],hours=sleep?+sleep.hours:0,quality=!sleep?'سجّل نومك':hours<5?'قليل جدًا':hours<7?'قليل':hours<=9?'جيد':hours<=10?'أكثر من المعتاد':'طويل جدًا';$('calGoal').textContent=num(calorieGoal);$('calEaten').textContent=`${num(eaten)} مأكول`; $('calGauge').style.setProperty('--progress',Math.min(100,eaten/Math.max(1,calorieGoal)*100)+'%');const macroTotals=foodToday.reduce((a,x)=>({protein:a.protein+(+x.protein||0),carbs:a.carbs+(+x.carbs||0),fat:a.fat+(+x.fat||0),fiber:a.fiber+(+x.fiber||0)}),{protein:0,carbs:0,fat:0,fiber:0});const macroTarget={protein:Math.round(p.weight*1.6),fat:Math.round(p.weight*0.8),carbs:Math.max(0,Math.round((calorieGoal-macroTargetSafe(p.weight)-Math.round(p.weight*0.8)*9)/4))};function macroTargetSafe(weight){return Math.round(weight*1.6)*4}if($('dailyMacros'))$('dailyMacros').innerHTML=[['البروتين',macroTotals.protein,macroTarget.protein,'جم','#77c8ff'],['الكربوهيدرات',macroTotals.carbs,macroTarget.carbs,'جم','#d7adff'],['الدهون',macroTotals.fat,macroTarget.fat,'جم','#ffd166'],['الألياف',macroTotals.fiber,25,'جم','#72d6a1']].map(a=>`<div class="fact" style="--fact:${a[4]}"><small>${a[0]} · الهدف ${a[2]} ${a[3]}</small><strong>${num(a[1],1)} <small>${a[3]}</small></strong><div class="macro-track"><span style="width:${Math.min(100,a[2]?a[1]/a[2]*100:0)}%"></span></div></div>`).join('');$('waterGoal').textContent=num(waterGoal);$('waterToday').textContent=`${num(water)} مل شربت`;$('waterGauge').style.setProperty('--progress',Math.min(100,water/Math.max(1,waterGoal)*100)+'%');$('sleepValue').textContent=sleep?num(hours,1):'—';$('sleepQuality').textContent=quality;$('sleepGauge').style.setProperty('--progress',Math.min(100,hours/8*100)+'%');$('waterLabel').textContent=`${num(water)} من ${num(waterGoal)} مل`;if($('homeWaterSummary'))$('homeWaterSummary').textContent=`${num(water)} من ${num(waterGoal)} مل اليوم` ;if($('waterPageProgress'))$('waterPageProgress').style.width=Math.min(100,water/Math.max(1,waterGoal)*100)+'%';$('homeCalories').textContent=`أكلت ${num(eaten)} من ${num(calorieGoal)} سعرة تقديرية اليوم.`;if($('needsSummary'))$('needsSummary').innerHTML=`<div class="needline"><span>السعرات الأساسية</span><b>${num(p.calories)} سعرة</b></div><div class="needline"><span>نشاط اليوم المقدر</span><b>+${num(Math.round(exerciseBurn))} سعرة</b></div><div class="needline"><span>هدف المياه اليوم</span><b>${num(waterGoal)} مل</b></div><div class="needline"><span>جودة النوم</span><b>${quality}</b></div><div class="needline"><span>وزنك / طولك</span><b>${p.weight} كجم / ${p.height} سم</b></div><div class="needline"><span>الهدف</span><b>${({cut:'تنشيف',bulk:'تضخيم',maintain:'الحفاظ على الوزن',fitness:'لياقة عامة'})[p.goal]}</b></div><p class="muted tiny">السعرات الإضافية تقديرية وتتغير حسب مدة النشاط وشدته. لو عمرك أقل من 18 سنة، استخدم الأرقام كمرشد عام وتجنب تغييرات كبيرة في الأكل بدون مختص.</p>`}

