function setupWorkoutBuilder(){if(!$('workoutDate'))return;$('workoutDate').value=today();const updateTargets=()=>{const ex=EXERCISES[$('workoutExercise').value];if($('workoutTargets'))$('workoutTargets').innerHTML=ex?Object.entries(ex.targets).sort((a,b)=>b[1]-a[1]).map(([m,w])=>`<span class="target-chip">${MUSCLES[m]} <b>${Math.round(w*100)}%</b></span>`).join(''):'—';if(ex?.timed){$('workoutReps').value=0;$('workoutSeconds').value=30}else{$('workoutReps').value=10;$('workoutSeconds').value=0}};$('workoutExercise').addEventListener('change',updateTargets);updateTargets();$('saveWorkoutSet').addEventListener('click',()=>{const key=$('workoutExercise').value,ex=EXERCISES[key],sets=+$('workoutSets').value,reps=+$('workoutReps').value,seconds=+$('workoutSeconds').value,date=$('workoutDate').value||today();if(!ex||!(sets>0&&sets<=20)||(!(reps>0)&&!(seconds>0))){alert('راجع عدد المجاميع والعدات أو الثواني.');return}const id=Date.now()+Math.random();db.logs.push({type:'workout',who:current,title:ex.name,exerciseKey:key,targets:ex.targets,sets,reps:reps||0,seconds:seconds||0,date,createdAt:date===today()?Date.now():new Date(date+'T12:00:00').getTime(),id});addPoints(current,sets*2);save();renderAll();});}
try{setupWorkoutBuilder()}catch(err){console.error('FitBros workout builder init:',err)}
function muscleRecovery(muscle){const now=Date.now();let fatigue=0;for(const x of ownLogs(current)){let targets={},volume=0,baseHours=48,stamp=0;if(x.type==='workout'){const ex=EXERCISES[x.exerciseKey];targets=x.targets||ex?.targets||(x.muscle?{[x.muscle]:1}:{});volume=Math.min(1.8,Math.max(.15,((+x.sets||1)*Math.max(1,+x.reps||(+x.seconds||30)/10))/30));baseHours=targets[muscle]&&targets[muscle]>=.4?60:48;stamp=Number(x.createdAt)||new Date((x.date||today())+'T12:00:00').getTime();}else if(x.type==='run'){const km=+x.km||0,min=+x.min||km*6;targets={calves:.30,quads:.22,hamstrings:.18,glutes:.20,abs:.05,lowerBack:.05};volume=Math.min(1.8,Math.max(.1,km/3+min/45));baseHours=km>=8?60:km>=4?48:36;stamp=Number(x.createdAt)||new Date((x.date||today())+'T12:00:00').getTime();}else continue;const share=targets[muscle]||0;if(!share)continue;const hours=Math.max(0,(now-stamp)/3600000);if(hours>baseHours*2)continue;const load=Math.min(72,share*volume*65);fatigue+=load*Math.exp(-hours/(baseHours/2.8));}return Math.max(0,Math.min(100,Math.round(100-fatigue)));}
function renderMuscleRecovery(){if(!$('muscleRecovery'))return;const keys=Object.keys(MUSCLES);$('muscleRecovery').innerHTML=keys.map(m=>{const recovery=muscleRecovery(m);return `<div class="recovery-item"><div class="recovery-head"><b>${MUSCLES[m]}</b><span>${recovery}% تعافٍ</span></div><div class="progress"><span style="width:${recovery}%;background:${recovery<40?'#ff5a00':recovery<75?'#ff8a38':'#8c969f'}"></span></div><small>${recovery<40?'إجهاد مرتفع نسبيًا — الراحة قد تفيد':recovery<75?'تعافٍ مستمر':'جاهزية تقديرية أعلى'}</small></div>`}).join('');document.querySelectorAll('.muscle-zone').forEach(el=>{const r=muscleRecovery(el.dataset.muscle);el.style.fill=`rgba(255,90,0,${Math.max(.05,(100-r)/100*.92)})`;el.style.opacity=String(Math.max(.15,(100-r)/100))})}
function renderDailyHistory(){
 const host=$("dailyHistoryList");if(!host)return;
 const logs=ownLogs(current);
 const dates=[...new Set(logs.filter(x=>["food","water","sleep"].includes(x.type)&&x.date).map(x=>x.date))].sort((a,b)=>b.localeCompare(a));
 if(!dates.length){host.innerHTML='<div class="panel muted">لسه مفيش أيام مسجلة لحسابك. أول ما تسجل أكل أو مياه أو نوم هيظهر هنا.</div>';return;}
 const safe=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
 host.innerHTML=dates.map(date=>{
  const day=logs.filter(x=>x.date===date),food=day.filter(x=>x.type==='food');
  const kcal=food.reduce((s,x)=>s+(Number(x.kcal)||0),0),protein=food.reduce((s,x)=>s+(Number(x.protein)||0),0);
  const water=day.filter(x=>x.type==='water').reduce((s,x)=>s+(Number(x.ml)||0),0),sleep=day.filter(x=>x.type==='sleep').reduce((s,x)=>Math.max(s,Number(x.hours)||0),0);
  const foods=food.length?food.map(x=>`<div class="history-food-row"><span><strong>${safe(x.title||'صنف')}</strong><small class="muted">${safe(x.meal||'وجبة')} · ${num(Number(x.grams)||0)} جم</small></span><b>${num(Number(x.kcal)||0)} سعر</b></div>`).join(''):'<p class="muted">مفيش أكل متسجل في اليوم ده.</p>';
  return `<article class="panel history-day"><button type="button" class="history-day-toggle" data-toggle-history="${safe(date)}" aria-expanded="false"><span class="history-date-title">📅 ${safe(prettyDate(date))}</span><span>🔥 ${num(kcal)} سعر <span class="history-chevron">⌄</span></span></button><div class="history-day-content hidden" id="history-content-${safe(date)}"><div class="history-metrics"><div><small>🔥 السعرات</small><b>${num(kcal)} سعرة</b></div><div><small>🥚 البروتين</small><b>${num(protein,1)} جم</b></div><div><small>💧 المياه</small><b>${num(water)} مل</b></div><div><small>🌙 النوم</small><b>${sleep?num(sleep,1)+' ساعة':'—'}</b></div></div><div class="history-day-food"><h4>🍽️ الأكل المسجل في اليوم</h4>${foods}</div><div class="history-day-actions"><button type="button" class="secondary compact danger-action" data-delete-history-day="${safe(date)}">حذف اليوم بالكامل</button></div></div></article>`;
 }).join('');
 host.querySelectorAll('[data-toggle-history]').forEach(b=>b.onclick=()=>{const box=$('history-content-'+b.dataset.toggleHistory);if(!box)return;box.classList.toggle('hidden');b.setAttribute('aria-expanded',String(!box.classList.contains('hidden')))});
 host.querySelectorAll('[data-delete-history-day]').forEach(b=>b.onclick=()=>{const date=b.dataset.deleteHistoryDay;if(!confirm(`متأكد إنك عايز تحذف كل تسجيلات يوم ${prettyDate(date)} من حسابك؟`))return;db.logs=db.logs.filter(x=>!(x.who===current&&x.date===date&&['food','water','sleep'].includes(x.type)));save();renderAll();showFoodToast('تم حذف تسجيلات اليوم')});
}
function renderAll(){renderDailyHistory();let w=ownLogs(current,'water').filter(x=>x.date===today()).reduce((s,x)=>s+(Number(x.ml)||0),0);$('myRunTotal').textContent=num(sumRun(current),2)+' كم';$('myWorkoutTotal').textContent=ownLogs(current).filter(x=>['run','exercise','workout','walk'].includes(x.type)).length+' تمرين';renderNeeds();renderList('foodLog',ownLogs(current,'food').filter(x=>x.who===current),x=>`<b>${x.kcal} سعر</b><br><small>${x.grams} جم · بروتين ${x.protein}جم · دهون ${x.fat}جم</small>`);let acts=db.logs.filter(x=>['run','exercise','workout','walk'].includes(x.type));if(activityFilter!=='all')acts=acts.filter(x=>x.type===activityFilter);renderList('activityLog',acts.filter(x=>x.who===current),x=>x.type==='run'?`<b>${num(x.km,2)} كم</b><br><small>${x.min||'—'} دقيقة · بيس ${num(x.pace||((+x.min||0)/(+x.km||1)),2)} دقيقة/كم</small>${x.trackPoints?gpsMiniRoute(x.trackPoints):''}`:x.type==='walk'?`<b>🚶 مشي</b><br><small>${x.steps?num(x.steps)+' خطوة · ':''}${num(x.km,2)} كم · ${num(x.min)} دقيقة</small>${x.trackPoints?gpsMiniRoute(x.trackPoints):''}`:x.type==='workout'?`<b>${x.title}</b><br><small>${x.sets} مجموعات × ${x.reps||'—'} عدة${x.seconds?' · '+x.seconds+' ثانية':''} · ${x.muscleName||MUSCLES[x.muscle]||''}</small>`:`<b>${x.min} دقيقة</b>`);renderList('activityHistoryLog',acts.filter(x=>x.who===current),x=>x.type==='run'?`<b>${num(x.km,2)} كم</b><br><small>${x.min||'—'} دقيقة · بيس ${num(x.pace||((+x.min||0)/(+x.km||1)),2)} دقيقة/كم</small>${x.trackPoints?gpsMiniRoute(x.trackPoints):''}`:x.type==='walk'?`<b>🚶 مشي</b><br><small>${x.steps?num(x.steps)+' خطوة · ':''}${num(x.km,2)} كم · ${num(x.min)} دقيقة</small>${x.trackPoints?gpsMiniRoute(x.trackPoints):''}`:x.type==='workout'?`<b>${x.title}</b><br><small>${x.sets} مجموعات × ${x.reps||'—'} عدة${x.seconds?' · '+x.seconds+' ثانية':''} · ${x.muscleName||MUSCLES[x.muscle]||''}</small>`:`<b>${x.min} دقيقة</b>`);renderList('sleepLog',ownLogs(current,'sleep'),x=>`<b>${x.hours} ساعة</b>`);renderCompare();renderChallenges();renderPlan();renderMuscleRecovery()}
document.querySelectorAll('[data-activity-filter]').forEach(b=>b.onclick=()=>{activityFilter=b.dataset.activityFilter;document.querySelectorAll('[data-activity-filter]').forEach(x=>x.classList.toggle('active',x.dataset.activityFilter===activityFilter));renderAll()});

